import win32com.client
import pandas as pd
from datetime import datetime, timedelta
import pythoncom

companeros = [{usuariosConsultar}]

hoy = datetime.now()
primer_dia_mes = hoy.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
fecha_fin      = hoy.replace(hour=23, minute=59, second=59, microsecond=0)

outlook = win32com.client.Dispatch("Outlook.Application").GetNamespace("MAPI")
eventos = []

def limpiar_texto_rpa(texto):
    if not texto:
        return ""
    t = str(texto)
    t = t.replace('"', "-")
    t = t.replace('\n', ' ').replace('\r', ' ')
    t = t.replace('/', '-').replace('|', '-')
    t = t.replace('\\', '')
    return t.strip()

def com_a_datetime(fecha_com):
    try:
        return datetime(
            fecha_com.year, fecha_com.month, fecha_com.day,
            fecha_com.hour, fecha_com.minute, fecha_com.second
        )
    except Exception:
        try:
            return fecha_com.replace(tzinfo=None)
        except Exception:
            return fecha_com

for alias in companeros:
    try:
        recipient = outlook.CreateRecipient(alias)
        recipient.Resolve()
        if not recipient.Resolved:
            print(f"No se pudo resolver: {alias}")
            continue

        calendar = outlook.GetSharedDefaultFolder(recipient, 9)
        items = calendar.Items

        items.IncludeRecurrences = True
        items.Sort("[Start]")

        count = 0
        for item in items:
            try:
                start = com_a_datetime(item.Start)

                if start > fecha_fin:
                    break

                if start < primer_dia_mes:
                    continue

                if item.Class != 26:
                    continue
                if not item.Categories or item.Categories.strip() == "":
                    continue

                #  FIX: Usar Duration para calcular end correctamente en series
                duracion_minutos = item.Duration
                end = start + timedelta(minutes=duracion_minutos)
                duracion_horas = round(duracion_minutos / 60, 2)

                eventos.append({
                    "Hit":              count + 1,
                    "Inicio":           start.strftime("%d-%m-%Y %H:%M"),
                    "Fin":              end.strftime("%d-%m-%Y %H:%M"),
                    "Asunto":           limpiar_texto_rpa(item.Subject),
                    "Ubicación":        limpiar_texto_rpa(item.Location),
                    "Usuario":          recipient.Name,
                    "Duración (horas)": duracion_horas,
                    "Categoría":        item.Categories.strip()
                })
                count += 1

            except Exception as e:
                print(f"  Error al leer evento: {e}")
                continue

        print(f"{recipient.Name}: {count} evento(s) encontrado(s) "
              f"({primer_dia_mes.strftime('%d/%m/%Y')}  {hoy.strftime('%d/%m/%Y %H:%M')})")

    except Exception as e:
        print(f"Error con {alias}: {str(e)}")

if eventos:
    SetVar("datosCalendario", eventos)
else:
    print("No se encontraron eventos con categoría en el rango indicado.")

